#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's quoting undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"; fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line). Idempotent. Creates ENV_FILE at mode 0600; writes through a symlink
# and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: issue 139, provider two-step sign-in and recovery access.
# Answers are yes/no, a method name, or a date. Never a code or secret.
# State lives in $ENV_FILE (outside the repo). The evidence file is rebuilt at the end.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=9
ENV_FILE="${ISSUE139_STATE_FILE:-${TMPDIR:-/tmp}/issue-139-wizard.state}"
umask 077

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
EVIDENCE="$REPO_ROOT/docs/security/issue-139-evidence.md"
TODAY="$(date +%F)"
INCOMPLETE=0

# Documentation checked on 2026-10-16. Unknown controls remain blockers.
# https://vercel.com/docs/two-factor-authentication
# https://docs.github.com/en/authentication/securing-your-account-with-two-factor-authentication-2fa/configuring-two-factor-authentication
# https://neon.com/docs/manage/accounts
# https://www.mongodb.com/docs/atlas/security-multi-factor-authentication/
# https://support.google.com/accounts/answer/185839
# https://support.google.com/accounts/answer/1187538
# https://support.claude.com/en/articles/13132885-set-up-single-sign-on-sso

method() {
  local key="$1" answer
  while true; do
    ask "$key" "Protection used (passkey / authenticator / both):"
    answer="$(printf '%s' "${!key}" | tr '[:upper:]' '[:lower:]')"
    case "$answer" in
      passkey|authenticator|both) write_env "$key" "$answer"; return ;;
      *) warn "Use passkey, authenticator, or both. Text messages do not qualify." ;;
    esac
  done
}

required_answer() {
  local key="$1" prompt="$2"
  while true; do
    ask "$key" "$prompt"
    [[ "${!key}" =~ [^[:space:]] ]] && break
    warn "Enter an observation, or enter 'unknown'."
  done
  write_env "$key" "${!key}"
}

# provider_body KEY "Name" "URL" "hint": the shared check for one provider.
# Saves KEY_STATUS (passed|blocker), KEY_METHOD, KEY_NOTE, KEY_DATE.
provider_body() {
  local k="$1" name="$2" url="$3" hint="$4"
  [[ -n "$url" ]] && open_url "$url"
  [[ -n "$hint" ]] && note "$hint"
  step "Check every way to log in to $name, including email and linked accounts."
  step "Each allowed method must require a passkey or an authenticator app."
  step "Set up and test a protected method before removing an old method."
  step "Save recovery material privately when the provider shows it."
  step "Remove unprotected methods and text-message codes only after that test."
  step "In a private browser window, test each allowed method. Keep this session open."
  note "A passkey can complete sign-in without a separate code prompt."
  note "A linked Google or GitHub login needs protection on that account too."
  required_answer "${k}_LOGINS" "Login methods checked (names only, no account addresses):"
  note "Never enter a code, password, setup key, or other secret here."
  if confirm "Did you verify every allowed login requires a passkey or authenticator, with no text-message option?"; then
    method "${k}_METHOD"
    write_env "${k}_STATUS" "passed"
    write_env "${k}_NOTE" ""
  else
    INCOMPLETE=1
    write_env "${k}_METHOD" "unverified"
    write_env "${k}_STATUS" "blocker"
    required_answer "${k}_NOTE" "Blocker (short observation, no secrets):"
  fi
  write_env "${k}_DATE" "$(date +%F)"
}

provider_stage() {
  stage "$2: two-step sign-in"
  provider_body "$@"
}

banner "Issue 139: provider two-step sign-in and recovery access"
say "Two-step sign-in adds proof beyond a password."
say "A passkey uses your device or security key to prove it is you."
say "An authenticator app generates short-lived sign-in codes."
say "This wizard records observations only. You change provider settings yourself."
say "No secrets go into this wizard, chat, GitHub, or the repository."
say "If a control is missing or unclear, record a blocker and continue."
pause "Press Enter to check Vercel."

provider_stage VERCEL "Vercel" "https://vercel.com/account/settings/authentication" \
  "Account Settings (not Project Settings) > Authentication. Turn on Two-Factor Authentication (it must not say Inactive): set up an Authenticator App and/or a Passkey. Email, Google and GitHub logins are listed under Sign-in Methods; Google and GitHub need their own two-step, checked in their stages. If a login method has no second step, that is a blocker."
provider_stage GITHUB "GitHub" "https://github.com/settings/security" \
  "Settings > Password and authentication > Two-factor authentication. Enable an authenticator app if needed. Save recovery codes privately. Add a passkey if wanted. Remove text-message authentication after testing the protected method."
provider_stage NEON "Neon" "https://console.neon.tech" \
  "Profile avatar > Account > Settings > Set up two-factor authentication. Scan the QR code with your authenticator and verify its code in Neon only. Passkeys are in the Account settings sidebar. Neon documents no recovery codes; stage 8 will record that limit."
provider_stage ATLAS "MongoDB Atlas (until deleted)" "https://account.mongodb.com/account/security/mfa" \
  "Account name > Manage your MongoDB Account > Login and Security. Set up Authenticator App or Security Key / Biometric. Test linked logins too. An email-only second step does not meet this issue. Do not delete Atlas."
provider_stage GCLOUD "Google Cloud owner" "https://myaccount.google.com/security" \
  "Select the Google account that owns the Cloud project. Security & sign-in > How you sign in to Google > 2-Step Verification. Set up an authenticator or passkey. Check other sign-in options for a weaker alternative. Backup codes are inside 2-Step Verification."
provider_stage ANTHROPIC "Anthropic Console" "https://console.anthropic.com/settings/profile" \
  "Check the Console account settings and every login offered on its sign-in page. Current documentation describes Organization and access > Authentication > Require SSO for some organizations. SSO means sign-in through another identity service. Do not buy a plan or change organization-wide settings here. If no suitable control exists on your account, record a blocker. Google sign-in alone does not prove that email login is protected."

stage "Other providers and deferred providers"
say "Question 1: is there a registrar or another provider you already use for DrillMap?"
EXTRA_COUNT=0
while confirm "Another already-used provider or registrar to check now?"; do
  EXTRA_COUNT=$((EXTRA_COUNT + 1))
  ask "EXTRA${EXTRA_COUNT}_NAME" "Provider name:"
  nv="EXTRA${EXTRA_COUNT}_NAME"; write_env "$nv" "${!nv}"
  required_answer "EXTRA${EXTRA_COUNT}_URL" "Provider security-page URL (https:// only, no tokens):"
  uv="EXTRA${EXTRA_COUNT}_URL"
  while [[ "${!uv}" != https://* ]]; do
    warn "Use an https:// provider URL."
    required_answer "$uv" "Provider security-page URL:"
  done
  provider_body "EXTRA${EXTRA_COUNT}" "${!nv}" "${!uv}" "The exact controls depend on this provider. If the path is unclear, record a blocker and ask for help."
done
write_env EXTRA_COUNT "$EXTRA_COUNT"
say "Question 2: name providers you will add later (for example an email provider). They are recorded as deferred, not passed."
ask DEFERRED "Deferred providers (comma list, or 'none'):"
write_env DEFERRED "$DEFERRED"

stage "Recovery codes"
say "Recovery codes can restore access after you lose a sign-in device."
say "For each provider, save its current codes in your password manager and print one copy."
say "Do not generate replacement codes unless needed. New codes can cancel the old set."
say "If replacement is needed, confirm that action in the provider before you proceed."
warn "Never paste codes into this wizard, chat, GitHub, or any repo file."
required_answer RECOVERY_METHOD "Password manager name only:"
recovery() {
  local key="$1" name="$2" url="$3"
  open_url "$url"
  say "Check recovery for $name in its account security settings."
  if [[ "$key" == NEON ]]; then
    warn "Neon documents no recovery codes. Do not mark this requirement complete."
    say "Keep the authenticator backed up or add a second passkey."
    write_env "${key}_RECOVERY" "blocker: provider does not offer recovery codes"
    INCOMPLETE=1
  elif confirm "$name: current recovery codes are in the password manager and one printed copy exists?"; then
    write_env "${key}_RECOVERY" "done"
  else
    INCOMPLETE=1
    required_answer "${key}_RECOVERY" "What is missing (no secrets; use 'blocker: ...')?"
  fi
  write_env "${key}_RECOVERY_DATE" "$(date +%F)"
}
recovery VERCEL Vercel "https://vercel.com/account/settings/authentication"
recovery GITHUB GitHub "https://github.com/settings/security"
recovery NEON Neon "https://console.neon.tech"
recovery ATLAS Atlas "https://account.mongodb.com/account/security/mfa"
recovery GCLOUD "Google Cloud owner" "https://myaccount.google.com/security"
recovery ANTHROPIC "Anthropic Console" "https://console.anthropic.com/settings/profile"
for ((i = 1; i <= EXTRA_COUNT; i++)); do
  nv="EXTRA${i}_NAME"; uv="EXTRA${i}_URL"
  recovery "EXTRA$i" "${!nv}" "${!uv}"
done

stage "Admin Google two-step sign-in"
say "Both intended Admins sign in to DrillMap through Google."
say "Each Admin checks their own Google account. You never see their codes or secrets."
open_url "https://myaccount.google.com/security"
step "Each Admin opens Security & sign-in > How you sign in to Google > 2-Step Verification."
step "Each Admin checks all allowed methods and removes text-message authentication."
step "Each Admin tests an authenticator or passkey sign-in in a private browser window."
note "A passkey sign-in need not show a separate second-step prompt."
warn "Each Admin keeps recovery material private. Do not collect it."
for n in 1 2; do
  if confirm "Admin $n: two-step is on, each allowed method meets the rule, and the protected sign-in worked?"; then
    method "ADMIN${n}_METHOD"
    write_env "ADMIN${n}_STATUS" "passed"
    write_env "ADMIN${n}_NOTE" ""
  else
    INCOMPLETE=1
    write_env "ADMIN${n}_STATUS" "blocker"
    write_env "ADMIN${n}_METHOD" "unverified"
    required_answer "ADMIN${n}_NOTE" "What remains unverified (no personal values or secrets)?"
  fi
  write_env "ADMIN${n}_DATE" "$(date +%F)"
done

# ── Build the local evidence file (no secrets) ────────────
val() { _existing "$1" || true; }
cell() {
  local value="$1"
  value="${value//|/&#124;}"
  value="${value//</&lt;}"
  value="${value//>/&gt;}"
  printf '%s' "$value"
}
row() { # KEY "Name"
  local s m n; s="$(val "${1}_STATUS")"; m="$(val "${1}_METHOD")"; n="$(val "${1}_NOTE")"
  printf '| %s | %s | %s | %s | %s | %s |\n' "$(cell "$2")" "${s:-not run}" "$(cell "$(val "${1}_LOGINS")")" "${m:--}" "$(val "${1}_DATE")" "$(cell "${n:--}")"
}

if [[ -e "$EVIDENCE" ]] && ! confirm "Replace the existing local issue-139 evidence file with this run?"; then
  say "Saved observations remain in $ENV_FILE. Existing evidence is unchanged."
  exit 0
fi

{
  printf '# Issue 139 evidence: provider two-step sign-in and recovery access\n\n'
  printf 'Date: %s. Recorded by the owner through a guided checklist. This file holds methods, states, and dates only. It holds no recovery code, secret, or Admin credential.\n\n' "$TODAY"
  printf 'No launch checklist row becomes passed from this ticket. Text-message codes are not allowed.\n\n'
  printf '## Provider login methods\n\n| Provider | State | Login methods checked | Protection | Date | Blocker |\n| --- | --- | --- | --- | --- | --- |\n'
  row VERCEL "Vercel"; row GITHUB "GitHub"; row NEON "Neon"; row ATLAS "MongoDB Atlas (until deletion)"
  row GCLOUD "Google Cloud owner"; row ANTHROPIC "Anthropic Console"
  for ((i = 1; i <= $(val EXTRA_COUNT); i++)); do row "EXTRA$i" "$(val "EXTRA${i}_NAME") (extra)"; done
  printf '\nDeferred providers (not passed): %s\n\n' "$(cell "$(val DEFERRED)")"
  printf '## Recovery codes\n\nPassword manager: %s. No codes collected.\n\n' "$(cell "$(val RECOVERY_METHOD)")"
  printf '| Provider | Password manager and printed copy | Date |\n| --- | --- | --- |\n'
  for key in VERCEL GITHUB NEON ATLAS GCLOUD ANTHROPIC; do
    printf '| %s | %s | %s |\n' "$key" "$(cell "$(val "${key}_RECOVERY")")" "$(val "${key}_RECOVERY_DATE")"
  done
  for ((i = 1; i <= EXTRA_COUNT; i++)); do
    printf '| %s | %s | %s |\n' "$(cell "$(val "EXTRA${i}_NAME")")" "$(cell "$(val "EXTRA${i}_RECOVERY")")" "$(val "EXTRA${i}_RECOVERY_DATE")"
  done
  printf '\n## Admin Google two-step sign-in\n\n| Admin | State | Method | Date | Blocker |\n| --- | --- | --- | --- | --- |\n'
  for n in 1 2; do
    printf '| Admin %s | %s | %s | %s | %s |\n' "$n" "$(val "ADMIN${n}_STATUS")" "$(val "ADMIN${n}_METHOD")" "$(val "ADMIN${n}_DATE")" "$(cell "$(val "ADMIN${n}_NOTE")")"
  done
  printf '\n## Documentation limits\n\n'
  printf 'Neon documents no recovery codes: https://neon.com/docs/manage/accounts. This remains a blocker under issue 139. No substitute is approved here.\n'
  printf 'Provider documentation guides the procedure. The owner observations above determine the recorded results.\n'
  printf '\nOverall result: '
  if (( INCOMPLETE )); then printf 'incomplete; keep issue 139 open.\n'; else printf 'ready for owner review.\n'; fi
} > "$EVIDENCE"

finish
say "Evidence written to: $EVIDENCE"
if (( INCOMPLETE )); then
  warn "At least one item is a blocker or not done. Keep issue 139 open."
else
  note "Checks are ready for review. This does not approve launch or close the issue."
fi
note "Review it for secrets, then tell the agent. State file you can delete: $ENV_FILE"
printf '\n'
